/* Browser OS — styles (Windows 11 / macOS flat design) */

:root {
  --font-stack: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --accent: #0078d4;
  --text: #1b1b1f;
  --text-secondary: #5b5b66;
  --window-bg: #fdfdfd;
  --titlebar-bg: #f3f3f3;
  --taskbar-bg: rgba(243, 243, 243, 0.78);
  --shadow: 0 12px 40px rgba(0, 0, 0, 0.28);
  --shadow-focused: 0 16px 52px rgba(0, 0, 0, 0.38);
  --radius: 10px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html,
body {
  height: 100%;
  overflow: hidden;
  font-family: var(--font-stack);
  color: var(--text);
  -webkit-user-select: none;
  user-select: none;
}

/* Desktop */
#desktop {
  position: fixed;
  inset: 0;
  background: #2a2a35;
  overflow: hidden;
}

.desktop-icons {
  position: absolute;
  top: 24px;
  left: 24px;
  display: flex;
  flex-direction: column;
  flex-wrap: wrap;
  gap: 8px;
  max-height: calc(100vh - 90px);
  align-content: flex-start;
}

.desktop-icon {
  width: 84px;
  padding: 10px 6px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  border-radius: 8px;
  cursor: pointer;
  text-align: center;
  color: #fff;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.55);
}

.desktop-icon:hover {
  background: rgba(255, 255, 255, 0.14);
}

.desktop-icon.selected {
  background: rgba(255, 255, 255, 0.24);
  outline: 1px solid rgba(255, 255, 255, 0.4);
}

.desktop-icon .icon-glyph {
  width: 42px;
  height: 42px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
  font-weight: 600;
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.25);
}

.desktop-icon .icon-label {
  font-size: 12px;
  line-height: 1.2;
  word-break: break-word;
}

/* Windows */
.windows {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.window {
  position: absolute;
  min-width: 280px;
  min-height: 180px;
  background: var(--window-bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  pointer-events: auto;
  transform: translate(var(--x, 0px), var(--y, 0px));
}

.window.focused {
  box-shadow: var(--shadow-focused);
}

.window-titlebar {
  height: 40px;
  flex: 0 0 40px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 8px 0 12px;
  background: var(--titlebar-bg);
  border-bottom: 1px solid #e6e6e6;
  cursor: default;
}

.window.focused .window-titlebar {
  background: #fafafa;
}

.window-titlebar .win-icon {
  width: 18px;
  height: 18px;
  border-radius: 5px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  color: #fff;
  flex: 0 0 auto;
}

.window-titlebar .win-title {
  flex: 1 1 auto;
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.window-titlebar .win-close {
  width: 30px;
  height: 30px;
  border: none;
  background: transparent;
  border-radius: 6px;
  font-size: 16px;
  line-height: 1;
  cursor: pointer;
  color: var(--text-secondary);
}

.window-titlebar .win-close:hover {
  background: #e81123;
  color: #fff;
}

.window-body {
  flex: 1 1 auto;
  position: relative;
  overflow: hidden;
  background: var(--window-bg);
}

.window-body .placeholder {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-secondary);
  font-size: 13px;
  text-align: center;
  padding: 16px;
}

/* Resize handle (optional, keeps windows within viewport) */
.window-resize {
  position: absolute;
  right: 0;
  bottom: 0;
  width: 16px;
  height: 16px;
  cursor: nwse-resize;
}

/* Taskbar */
.taskbar {
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  height: 48px;
  background: var(--taskbar-bg);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-top: 1px solid rgba(255, 255, 255, 0.6);
  display: flex;
  align-items: center;
  padding: 0 10px;
  gap: 8px;
  z-index: 10000;
}

.taskbar-buttons {
  flex: 1 1 auto;
  display: flex;
  align-items: center;
  gap: 6px;
  overflow: hidden;
}

.taskbar-button {
  height: 38px;
  min-width: 44px;
  padding: 0 14px;
  border: none;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.5);
  color: var(--text);
  font-family: var(--font-stack);
  font-size: 13px;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 8px;
  flex: 0 0 auto;
  max-width: 200px;
}

.taskbar-button .tb-icon {
  width: 18px;
  height: 18px;
  border-radius: 5px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  color: #fff;
  flex: 0 0 auto;
}

.taskbar-button .tb-label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.taskbar-button:hover {
  background: rgba(255, 255, 255, 0.8);
}

.taskbar-button.active {
  background: rgba(255, 255, 255, 0.95);
  box-shadow: inset 0 2px 0 var(--accent), 0 1px 4px rgba(0, 0, 0, 0.12);
}

.taskbar-button.active::after {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent);
  position: absolute;
  bottom: 3px;
  left: 50%;
  transform: translateX(-50%);
}

.clock {
  flex: 0 0 auto;
  font-size: 13px;
  padding: 0 10px;
  color: var(--text);
  min-width: 62px;
  text-align: center;
}

/* Browser OS — Desktop shell: Window manager and taskbar (Ticket 1) */

"use strict";

/* ------------------------------------------------------------------ *
 * App registry
 * Each app defines an id, display name, taskbar/desktop icon glyph and
 * color, and a function that builds the window body content. At this
 * stage the apps are placeholders; their real content is added in later
 * tickets. The window manager itself is fully functional.
 * ------------------------------------------------------------------ */

const APPS = {
  notepad: {
    id: "notepad",
    name: "Notepad",
    glyph: "N",
    color: "#0078d4",
    buildContent: () => buildPlaceholder("Notepad", "Document content loads here (Ticket 4)."),
  },
  calculator: {
    id: "calculator",
    name: "Calculator",
    glyph: "=",
    color: "#2b6cb0",
    buildContent: () => buildPlaceholder("Calculator", "Calculator loads here (Ticket 3)."),
  },
  minesweeper: {
    id: "minesweeper",
    name: "Minesweeper",
    glyph: "M",
    color: "#c53030",
    buildContent: () => buildPlaceholder("Minesweeper", "Board loads here (Ticket 5)."),
  },
  spider: {
    id: "spider",
    name: "Spider Solitaire",
    glyph: "S",
    color: "#2f855a",
    buildContent: () => buildPlaceholder("Spider Solitaire", "Tableau loads here (Ticket 6)."),
  },
};

/* Build a simple placeholder body for apps not yet implemented. */
function buildPlaceholder(title, hint) {
  const body = document.createElement("div");
  body.className = "window-body";
  body.innerHTML =
    '<div class="placeholder"><div><strong>' +
    title +
    "</strong><br>" +
    hint +
    "</div></div>";
  return body;
}

/* ------------------------------------------------------------------ *
 * Window manager
 * Manages creation, focus/z-order, dragging, sizing constraints and
 * closing of application windows. One instance per app is kept.
 * ------------------------------------------------------------------ */

class WindowManager {
  constructor() {
    this.windows = new Map(); // appId -> window element
    this.state = new Map(); // appId -> { el, z, app }
    this.zCounter = 100;
    this.windowsContainer = document.getElementById("windows");
    this.taskbarButtons = document.getElementById("taskbar-buttons");
  }

  /* Open (or focus) the app for the given id. Single instance per app. */
  open(appId) {
    const app = APPS[appId];
    if (!app) return;

    if (this.state.has(appId)) {
      this.focus(appId);
      return;
    }

    const el = this._createWindowEl(app);
    this.state.set(appId, { el, z: ++this.zCounter, app });
    this.windowsContainer.appendChild(el);
    this._buildTaskbarButton(appId);
    this.focus(appId);
  }

  /* Focus an open window, raising it in the z-order. */
  focus(appId) {
    const s = this.state.get(appId);
    if (!s) return;
    s.z = ++this.zCounter;
    s.el.style.zIndex = s.z;
    s.el.classList.add("focused");

    // Unfocus all others.
    for (const [id, st] of this.state.entries()) {
      if (id === appId) continue;
      st.el.classList.remove("focused");
      const btn = this.taskbarButtons.querySelector('[data-app="' + id + '"]');
      if (btn) btn.classList.remove("active");
    }
    const activeBtn = this.taskbarButtons.querySelector('[data-app="' + appId + '"]');
    if (activeBtn) activeBtn.classList.add("active");
  }

  /* Close a window by app id. */
  close(appId) {
    const s = this.state.get(appId);
    if (!s) return;
    s.el.remove();
    this.state.delete(appId);
    const btn = this.taskbarButtons.querySelector('[data-app="' + appId + '"]');
    if (btn) btn.remove();
  }

  /* Close the most recently focused window helper (unused here). */
  closeFocused() {}

  /* Create the DOM for a new window. */
  _createWindowEl(app) {
    const el = document.createElement("div");
    el.className = "window";
    // Cascade new windows so they don't stack exactly on top of each other.
    const offset = this.state.size * 28;
    el.style.setProperty("--x", (80 + offset) + "px");
    el.style.setProperty("--y", (50 + offset) + "px");
    el.style.width = "460px";
    el.style.height = "320px";

    const titlebar = document.createElement("div");
    titlebar.className = "window-titlebar";

    const icon = document.createElement("div");
    icon.className = "win-icon";
    icon.textContent = app.glyph;
    icon.style.background = app.color;

    const title = document.createElement("div");
    title.className = "win-title";
    title.textContent = app.name;

    const close = document.createElement("button");
    close.className = "win-close";
    close.setAttribute("aria-label", "Close");
    close.textContent = "✕";
    close.addEventListener("click", (e) => {
      e.stopPropagation();
      this.close(app.id);
    });

    titlebar.append(icon, title, close);

    const body = document.createElement("div");
    body.className = "window-body";
    body.appendChild(app.buildContent());

    el.append(titlebar, body);

    // Focus on mousedown anywhere in the window.
    el.addEventListener("mousedown", () => this.focus(app.id));

    // Draggable by the title bar.
    this._setupDrag(el, titlebar, app.id);

    return el;
  }

  /* Make a window draggable via the given handle, constrained to viewport. */
  _setupDrag(el, handle, appId) {
    let dragging = false;
    let startX = 0;
    let startY = 0;
    let origX = 0;
    let origY = 0;

    handle.addEventListener("mousedown", (e) => {
      if (e.target.closest(".win-close")) return;
      e.preventDefault();
      dragging = true;
      startX = e.clientX;
      startY = e.clientY;
      origX = parseInt(el.style.getPropertyValue("--x") || "0", 10);
      origY = parseInt(el.style.getPropertyValue("--y") || "0", 10);
      this.focus(appId);

      const onMove = (ev) => {
        if (!dragging) return;
        const taskbarH = 48;
        const maxW = window.innerWidth - 8;
        const maxH = window.innerHeight - taskbarH - 8;
        let nx = origX + (ev.clientX - startX);
        let ny = origY + (ev.clientY - startY);
        nx = Math.max(-el.offsetWidth + 80, Math.min(nx, maxW));
        ny = Math.max(0, Math.min(ny, maxH));
        el.style.setProperty("--x", nx + "px");
        el.style.setProperty("--y", ny + "px");
      };

      const onUp = () => {
        dragging = false;
        window.removeEventListener("mousemove", onMove);
        window.removeEventListener("mouseup", onUp);
      };

      window.addEventListener("mousemove", onMove);
      window.addEventListener("mouseup", onUp);
    });
  }

  /* Build (or update) a taskbar button for the app. */
  _buildTaskbarButton(app) {
    const btn = document.createElement("button");
    btn.className = "taskbar-button";
    btn.setAttribute("data-app", app.id);

    const icon = document.createElement("span");
    icon.className = "tb-icon";
    icon.textContent = app.glyph;
    icon.style.background = app.color;

    const label = document.createElement("span");
    label.className = "tb-label";
    label.textContent = app.name;

    btn.append(icon, label);
    btn.addEventListener("click", () => this.focus(app.id));
    this.taskbarButtons.appendChild(btn);
  }
}

/* ------------------------------------------------------------------ *
 * Desktop shell wiring: icons, taskbar, clock.
 * ------------------------------------------------------------------ */

function renderDesktopIcons() {
  const container = document.getElementById("desktop-icons");
  container.innerHTML = "";
  for (const app of Object.values(APPS)) {
    const icon = document.createElement("div");
    icon.className = "desktop-icon";
    icon.setAttribute("data-app", app.id);

    const glyph = document.createElement("div");
    glyph.className = "icon-glyph";
    glyph.textContent = app.glyph;
    glyph.style.background = app.color;

    const label = document.createElement("div");
    label.className = "icon-label";
    label.textContent = app.name;

    icon.append(glyph, label);

    // Single click selects; double click opens.
    icon.addEventListener("click", (e) => {
      document
        .querySelectorAll(".desktop-icon.selected")
        .forEach((n) => n.classList.remove("selected"));
      icon.classList.add("selected");
    });
    icon.addEventListener("dblclick", () => wm.open(app.id));

    container.appendChild(icon);
  }
}

/* Update the HH:MM clock in the taskbar every second. */
function startClock() {
  const clockEl = document.getElementById("clock");
  const tick = () => {
    const now = new Date();
    const hh = String(now.getHours()).padStart(2, "0");
    const mm = String(now.getMinutes()).padStart(2, "0");
    clockEl.textContent = hh + ":" + mm;
  };
  tick();
  setInterval(tick, 1000);
}

/* Clicking empty desktop area clears icon selection. */
function setupDesktopInteraction() {
  const desktop = document.getElementById("desktop");
  desktop.addEventListener("click", (e) => {
    if (e.target.id === "desktop" || e.target.id === "desktop-icons") {
      document
        .querySelectorAll(".desktop-icon.selected")
        .forEach((n) => n.classList.remove("selected"));
    }
  });
}

/* ------------------------------------------------------------------ *
 * Init
 * ------------------------------------------------------------------ */

const wm = new WindowManager();

document.addEventListener("DOMContentLoaded", () => {
  renderDesktopIcons();
  startClock();
  setupDesktopInteraction();
});

// Expose the window manager for debugging / testing in the browser.
window.__wm = wm;
window.APPS = APPS;

