/* 3. Sunset — warm pink/orange gradient */
#desktop.wp-sunset,
.wp-sunset { background: linear-gradient(135deg, #f5af19, #d5435f); }

/* 4. Twilight — deep indigo to navy */
#desktop.wp-twilight,
.wp-twilight { background: linear-gradient(135deg, #141e30, #243b55); }

/* 5. Rose — solid muted rose */
#desktop.wp-rose,
.wp-rose { background: #c2185b; }

/* 6. Sage — solid muted sage green */
#desktop.wp-sage,
.wp-sage { background: #4d7a5a; }

/* 7. Sand — solid warm sand */
#desktop.wp-sand,
.wp-sand { background: #b08d57; }

/* 8. Stripes — repeating diagonal pattern (CSS pattern) */
#desktop.wp-stripes,
.wp-stripes {
  background:
    repeating-linear-gradient(
      45deg,
      #3a4a5a 0px,
      #3a4a5a 14px,
      #4a5f75 14px,
      #4a5f75 28px
    );
}

/* 9. Graph — repeating grid pattern (CSS pattern) */
#desktop.wp-graph,
.wp-graph {
  background-color: #2b3a4a;
  background-image:
    linear-gradient(to right, rgba(255, 255, 255, 0.06) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(255, 255, 255, 0.06) 1px, transparent 1px);
  background-size: 32px 32px;
}

/* 10. Dots — repeating dotted pattern (CSS pattern) */
#desktop.wp-dots,
.wp-dots {
  background-color: #22303c;
  background-image: radial-gradient(rgba(255, 255, 255, 0.14) 2px, transparent 2px);
  background-size: 24px 24px;
}

