edits.newText:
.wp-thumbnail.selected .wp-check {
  display: flex;
}

/* -- Calculator (Ticket 3) -----------------------------------------
   Fills the window body: a two-line display above a 4-key grid.
   The grid has 5 rows; the leading 0 spans two columns. */

.calc {
  display: flex;
  flex-direction: column;
  height: 100%;
  background: var(--window-bg);
}

.calc-display {
  flex: 0 0 auto;
  padding: 14px 16px 10px;
  background: #f7f7f8;
  border-bottom: 1px solid #ececec;
  min-height: 88px;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  justify-content: flex-end;
  gap: 4px;
  overflow: hidden;
}

.calc-prev {
  font-size: 13px;
  color: var(--text-secondary);
  min-height: 16px;
  word-break: break-all;
  text-align: right;
  width: 100%;
}

.calc-current {
  font-size: 34px;
  font-weight: 500;
  color: var(--text);
  line-height: 1.1;
  word-break: break-all;
  text-align: right;
  width: 100%;
}

.calc-keys {
  flex: 1 1 auto;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  grid-template-rows: repeat(5, 1fr);
  gap: 8px;
  padding: 10px;
}

.calc-key {
  border: none;
  border-radius: 8px;
  background: #eef0f2;
  color: var(--text);
  font-family: var(--font-stack);
  font-size: 18px;
  font-weight: 500;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 40px;
  transition: background 0.08s ease, transform 0.05s ease;
}

.calc-key:active {
  transform: scale(0.97);
}

.calc-key:hover {
  background: #e4e7ea;
}

/* Operator keys (÷ × − +) */
.calc-key.op {
  background: #dcdfe3;
  color: #2b2b30;
}

.calc-key.op:hover {
  background: #d0d4d9;
}

/* Control keys (C ± %) */
.calc-key.ctrl {
  background: #e2e6ea;
  color: #3a3a40;
}

.calc-key.ctrl:hover {
  background: #d6dbe0;
}

/* Equals key */
.calc-key.equals {
  background: var(--accent);
  color: #fff;
}

.calc-key.equals:hover {
  filter: brightness(1.05);
}

/* Leading 0 spans two columns. */
.calc-key.wide {
  grid-column: span 2;
}

