chrome-devtools-axi eval "() => {
  const c = window.__getCalc();
  const results = [];
  function run(label, fn, expected) {
    fn();
    const cur = c.current;
    const ok = (expected === undefined) || (cur === expected);
    results.push(label + ' => ' + JSON.stringify(cur) + (ok ? ' OK' : ' FAIL (expected ' + JSON.stringify(expected) + ')'));
  }
  // 2 + 3 = 5
  run('2+3=', () => { c._onKey('2'); c._onKey('+'); c._onKey('3'); c._onKey('='); }, '5');
  // 10 - 4 = 6
  run('10-4=', () => { c.clear(); c._onKey('1'); c._onKey('0'); c._onKey('−'); c._onKey('4'); c._onKey('='); }, '6');
  // 6 * 7 = 42
  run('6*7=', () => { c.clear(); c._onKey('6'); c._onKey('×'); c._onKey('7'); c._onKey('='); }, '42');
  // 84 / 7 = 12
  run('84/7=', () => { c.clear(); c._onKey('8'); c._onKey('4'); c._onKey('÷'); c._onKey('7'); c._onKey('='); }, '12');
  // immediate: 2 + 3 + 4 = 9
  run('2+3+4=', () => { c.clear(); c._onKey('2'); c._onKey('+'); c._onKey('3'); c._onKey('+'); c._onKey('4'); c._onKey('='); }, '9');
  // decimal 1.5 + 0.5 = 2
  run('1.5+0.5=', () => { c.clear(); c._onKey('1'); c._onKey('.'); c._onKey('5'); c._onKey('+'); c._onKey('0'); c._onKey('.'); c._onKey('5'); c._onKey('='); }, '2');
  // divide by zero
  run('5/0=', () => { c.clear(); c._onKey('5'); c._onKey('÷'); c._onKey('0'); c._onKey('='); }, 'Error');
  // after error, next input clears
  run('after err, 3 ()', () => { c._onKey('3'); }, '3');
  // percent 50% = 0.5
  run('50%', () => { c.clear(); c._onKey('5'); c._onKey('0'); c._onKey('%'); }, '0.5');
  // sign -5
  run('-5 sign', () => { c.clear(); c._onKey('5'); c._onKey('±'); }, '-5');
  // backspace
  run('12 backspace', () => { c.clear(); c._onKey('1'); c._onKey('2'); c.backspace(); }, '1');
  results.join('\n');
}" 2>&1 | head -30

