/* -- Notepad (Ticket 4) --------------------------------------------
   Fills the window body with a left sidebar (actions + document list)
   and a full-height textarea for the active document. Documents are
   named and persisted in localStorage. */

.notepad {
  display: flex;
  height: 100%;
  background: var(--window-bg);
  overflow: hidden;
}

.notepad-sidebar {
  width: 190px;
  flex: 0 0 190px;
  display: flex;
  flex-direction: column;
  background: #f5f5f6;
  border-right: 1px solid #e8e8e8;
  overflow: hidden;
}

