_placeMines(safeR, safeC) {
  const { rows, cols, mines } = this._diff();
  const total = rows * cols;
  if (mines >= total - 1) {
    // edge case, but our configs never hit this
  }
  // build list of possible positions excluding safe zone
  const safe = new Set();
  safe.add(safeR + "," + safeC);
  for (const [nr, nc] of this._neighbors(safeR, safeC)) {
    safe.add(nr + "," + nc);
  }
  const candidates = [];
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (!safe.has(r + "," + c)) candidates.push([r, c]);
    }
  }
  // shuffle
  for (let i = candidates.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [candidates[i], candidates[j]] = [candidates[j], candidates[i]];
  }
  // mark mines
  for (let i = 0; i < mines && i < candidates.length; i++) {
    const [r, c] = candidates[i];
    this.board[r][c].mine = true;
  }
  // compute adjacent
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (this.board[r][c].mine) continue;
      let count = 0;
      for (const [nr, nc] of this._neighbors(r, c)) {
        if (this.board[nr][nc].mine) count++;
      }
      this.board[r][c].adjacent = count;
    }
  }
}
