/* -- Minesweeper (Ticket 5) ----------------------------------------
   Flat, Windows 11 / macOS inspired board. A control bar (difficulty
   selector + restart), a status row (mine counter + timer) and a CSS
   grid board. Cell size is set per difficulty via --ms-cell so the
   board fits the window. */

.minesweeper {
  display: flex;
  flex-direction: column;
  height: 100%;
  background: var(--window-bg);
  padding: 10px;
  gap: 8px;
  box-sizing: border-box;
  color: var(--text);
}

.minesweeper-title {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  color: var(--text-secondary);
  padding: 0 2px;
}

.ms-control {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px;
  background: #f5f5f6;
  border: 1px solid #e8e8e8;
  border-radius: 8px;
}

.ms-diff {
  border: 1px solid transparent;
  border-radius: 7px;
  padding: 6px 12px;
  font-family: var(--font-stack);
  font-size: 12px;
  font-weight: 500;
  color: var(--text);
  background: transparent;
  cursor: pointer;
  flex: 0 0 auto;
}

.ms-diff:hover {
  background: #e9ecef;
}

.ms-diff.active {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

.ms-restart {
  margin-left: auto;
  width: 34px;
  height: 34px;
  border: 1px solid #e0e0e0;
  border-radius: 8px;
  background: #fbfbfb;
  font-size: 20px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
}

.ms-restart:hover {
  background: #f0f0f0;
}

.ms-status {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 6px 10px;
  background: #2f2f35;
  border-radius: 8px;
}

.ms-mines,
.ms-timer {
  font-family: "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 22px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: #fff;
  background: #111114;
  padding: 4px 10px;
  border-radius: 6px;
  min-width: 62px;
  text-align: center;
  letter-spacing: 1px;
}

.ms-timer {
  text-align: right;
}

.ms-board {
  flex: 1 1 auto;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  overflow: auto;
  padding: 4px;
}

.ms-grid {
  display: grid;
  gap: 2px;
  padding: 6px;
  background: #d7d7db;
  border-radius: 8px;
  box-shadow: inset 0 1px 3px rgba(0, 0, 0, 0.18);
}

.ms-cell {
  width: var(--ms-cell, 26px);
  height: var(--ms-cell, 26px);
  border: none;
  border-radius: 4px;
  font-family: var(--font-stack);
  font-size: 14px;
  font-weight: 700;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #c9ccd1;
