+  }
+
+  /* Determine whether every non-mine cell has been revealed. */
+  _checkWin() {
+    const total = this.rows * this.cols;
+    if (this.revealed === total - this.mineCount) {
+      this._win();
+    }
+  }
+
+  /* Loss: reveal all mines, lock the board, stop the timer. */
+  _lose(r, c) {
