+    this._setResult(false);
+  }
+
+  /* Win: flag all remaining mines, stop the timer. */
+  _win() {
+    this.gameOver = true;
+    this.won = true;
+    this._stopTimer();
+    this.restartEl.textContent = "😎";
+    // Flag every unrevealed mine.
+    for (let rr = 0; rr < this.rows; rr++) {
+      for (let cc = 0; cc < this.cols; cc++) {
