/* Build the Minesweeper app content. */
function buildMinesweeper() {
  const el = document.createElement("div");
  const ms = new Minesweeper(el);
  return { el, instance: ms };
}

/* ------------------------------------------------------------------ *
 * IN-PAGE SELF-TEST (Minesweeper, Ticket 5)
 * Steps the game with scripted inputs, asserts the rules in code and
 * prints one PASS/FAIL summary. State samples are logged only on
 * failure. Remove this block when done developing.
 * ------------------------------------------------------------------ */
window.__testMinesweeper = function () {
  const results = [];
  const log = (name, ok, sample) =>
    results.push({ name, ok, sample });

  /* Create a detached Minesweeper instance (never attached to the DOM). */
  function make(diff) {
    const host = document.createElement("div");
    const ms = new Minesweeper(host);
    ms.setDifficulty(diff);
    return ms;
  }

  /* --- Scenario 1: first click is always safe + mines placed --- */
  (function () {
    const ms = make("beginner");
    ms.stepReveal(0, 0);
    const s = ms.getState();
    const neighbors = ms._neighbors(0, 0);
    const safeZone = [0 + ",0", ...neighbors.map(([r, c]) => r + "," + c)];
    const anyMine = safeZone.some((key) => {
      const [r, c] = key.split(",").map(Number);
      return ms.board[r][c].mine;
    });
    log("First click safe + mines placed", s.minesPlaced && !anyMine && ms.board[0][0].revealed && !ms.board[0][0].mine, s);
  })();

  /* --- Scenario 2: flood fill expands on zero cells --- */
  (function () {
    const ms = make("beginner");
    ms.stepReveal(0, 0);
    const before = ms.revealed;
    // Reveal a centre cell; if it is a zero, neighbours get revealed too.
    const midR = Math.floor(ms.rows / 2);
    const midC = Math.floor(ms.cols / 2);
    ms.stepReveal(midR, midC);
    const after = ms.revealed;
    // Either the mid cell was a number (no expansion) or it flood-filled.
    const expanded = after >= before;
    log("Flood fill expands on zeros", expanded && after > 0, { before, after, midCell: ms.board[midR][midC] });
  })();

  /* --- Scenario 3: flag toggling updates the counter --- */
  (function () {
    const ms = make("beginner");
    ms.stepReveal(0, 0);
    const startFlags = ms.flags;
    ms.stepFlag(1, 1);
    const afterOne = ms.flags;
    ms.stepFlag(1, 1);
    const afterTwo = ms.flags;
    log("Flag toggling", afterOne === startFlags + 1 && afterTwo === startFlags, { startFlags, afterOne, afterTwo });
  })();

  /* --- Scenario 4: win detection --- */
  (function () {
    const ms = make("intermediate");
    ms.stepReveal(0, 0); // trigger mine placement
    // Reveal every non-mine cell.
    for (let r = 0; r < ms.rows; r++) {
      for (let c = 0; c < ms.cols; c++) {
        if (!ms.board[r][c].mine) ms.stepReveal(r, c);
      }
    }
    const s = ms.getState();
    log("Win detection", s.gameOver && s.won === true && s.timer === ms.timer, s);
  })();

  /* --- Scenario 5: loss detection + board reveal --- */
  (function () {
    const ms = make("expert");
    ms.stepReveal(0, 0); // safe first click
    // Find a mine cell and step on it.
    let mineCell = null;
    for (let r = 0; r < ms.rows && !mineCell; r++) {
      for (let c = 0; c < ms.cols && !mineCell; c++) {
        if (ms.board[r][c].mine) mineCell = [r, c];
      }
    }
    ms.stepReveal(mineCell[0], mineCell[1]);
    const s = ms.getState();
    // All mines should be revealed after a loss.
    const allMinesRevealed = ms.board.every((row) =>
      row.every((cell) => !cell.mine || cell.revealed)
    );
    log("Loss detection + reveal", s.gameOver && s.won === false && allMinesRevealed, s);
  })();

  /* --- Scenario 6: timer starts on first click, stops on end --- */
  (function () {
    const ms = make("beginner");
    const beforeInterval = ms._timerInterval;
    ms.stepReveal(0, 0);
    const afterStart = ms._timerInterval;
    ms.stepFlag(0, 1);
    ms.stepFlag(0, 2);
    ms.stepFlag(0, 3);
    ms.stepFlag(0, 4);
    ms.stepFlag(0, 5);
    ms.stepFlag(0, 6);
    ms.stepFlag(0, 7);
    ms.stepFlag(0, 8);
    ms.stepFlag(0, 9);
    ms.stepFlag(0, 10);
    // Force a loss by stepping on a mine.
    let mineCell = null;
    for (let r = 0; r < ms.rows && !mineCell; r++) {
      for (let c = 0; c < ms.cols && !mineCell; c++) {
        if (ms.board[r][c].mine) mineCell = [r, c];
      }
    }
    ms.stepReveal(mineCell[0], mineCell[1]);
    const afterEnd = ms._timerInterval;
    log(
      "Timer start/stop",
      beforeInterval === null && afterStart !== null && afterEnd === null,
      { beforeInterval: !!beforeInterval, afterStart: !!afterStart, afterEnd: !!afterEnd }
    );
  })();

  /* --- Scenario 7: mine count matches difficulty --- */
  (function () {
    const ms = make("expert");
    const mineTotal = ms.board.reduce((sum, row) =>
      sum + row.filter((c) => c.mine).length, 0
    );
    log("Mine count matches config", mineTotal === 99, { mineTotal });
  })();

  /* Summary */
  const failed = results.filter((r) => !r.ok);
  const lines = results.map((r) => (r.ok ? "PASS" : "FAIL") + " - " + r.name);
  if (failed.length) {
    lines.push("");
    failed.forEach((r) => lines.push("  Sample: " + JSON.stringify(r.sample)));
  }
  lines.push("");
  lines.push((failed.length ? "FAIL" : "PASS") + " (" + (results.length - failed.length) + "/" + results.length + " checks passed)");
  console.log(lines.join("\n"));
  return { passed: failed.length === 0, total: results.length, failed: failed.length };
};

