chrome-devtools-axi open "file://$PWD/index.html" 2>&1 | tail -2; sleep 2; chrome-devtools-axi eval "() => {
  const out = {};
  wm.open('minesweeper');
  const ms = window.__getMinesweeper();
  ms.setDifficulty('beginner');
  ms.stepReveal(4,4);
  const s1 = ms.getState();
  // win
  for (let r=0;r<ms.rows;r++) for (let c=0;c<ms.cols;c++) if(!ms.board[r][c].mine) ms.stepReveal(r,c);
  const s2 = ms.getState();
  // loss on new game
  ms.newGame();
  ms.stepReveal(0,0);
  let mine=null; for(let r=0;r<ms.rows&&!mine;r++)for(let c=0;c<ms.cols&&!mine;c++)if(ms.board[r][c].mine)mine=[r,c];
  ms.stepReveal(mine[0],mine[1]);
  const s3 = ms.getState();
  out.afterFirstReveal = {revealed:s1.revealed, minesPlaced:s1.minesPlaced, timerStarted:!!ms._timerInterval};
  out.win = s2.gameOver && s2.won;
  out.loss = s3.gameOver && !s3.won;
  out.difficulties = ['beginner','intermediate','expert'].map(d=>{ms.setDifficulty(d);const x=ms.getState();return d+':'+x.rows+'x'+x.cols+'/'+x.mineCount;});
  return out;
}" 2>&1 | head

chrome-devtools-axi eval "() => {
  const ms = window.__getMinesweeper();
  ms.setDifficulty('beginner');
  ms.newGame();
  const before = ms._timerInterval;
  ms.stepReveal(4,4);
  const after = ms._timerInterval;
  return { before: !!before, after: !!after, timer: ms.timer, timerText: ms.timerEl.textContent };
}" 2>&1 | head

