      colEl.className = "spider-col";
      colEl.setAttribute("data-col", c);

      if (col.length === 0) {
        const empty = document.createElement("div");
        empty.className = "spider-col-empty";
        empty.textContent = "\u2660";
        colEl.appendChild(empty);
