  assert(s._canMove(0,0)===false, "cannot move onto same column");
  s.columns=[[{rank:6,faceUp:true}],[{rank:5,faceUp:true}]];
  assert(s._canMove(0,1)===false, "cannot put 6 on 5");

  // --- moveGroup results ---
